style:
body{
    background:#F8FAFC;
    font-family:Inter,sans-serif;
}

.welcome-card{
    width:100%;
    background:white;
    padding:45px;
    border-radius:20px;
    box-shadow:0 10px 25px rgba(0,0,0,.08);
    box-sizing:border-box;
    text-align:center;
    margin-bottom:35px;
}

.welcome-card h1{

    font-size:48px;

    color:#153D35;

    margin-bottom:15px;

    font-weight:700;

}

.subtitle{

    width:70%;

    margin:auto;

    color:#666;

    font-size:18px;

    line-height:1.8;

    margin-bottom:35px;

}

.ticker{

    background:#D67A9B;

    color:white;

    padding:14px;

    border-radius:12px;

    overflow:hidden;

    white-space:nowrap;

    margin-bottom:40px;

}

.ticker span{

    display:inline-block;

    padding-left:100%;

    animation:scroll 20s linear infinite;

}

@keyframes scroll{

from{

transform:translateX(0);

}

to{

transform:translateX(-100%);

}

}

.quick-links{

display:grid;

grid-template-columns:repeat(auto-fit,minmax(220px,1fr));

gap:20px;

}

.item{

background:#F8FAFC;

border:1px solid #E8EDF3;

border-radius:15px;

padding:28px 20px;

cursor:pointer;

transition:.35s;

}

.item:hover{

background:#D7C3CF;

transform:translateY(-6px);

box-shadow:0 10px 20px rgba(0,0,0,.08);

}

.icon{

font-size:38px;

margin-bottom:20px;

}

.item h3{

color:#153D35;

font-size:20px;

margin-bottom:10px;

}

.item p{

color:#666;

font-size:15px;

line-height:1.6;

}
